import{_ as t,o as r,c as o,a2 as a}from"./chunks/framework.il0noOp3.js";const p=JSON.parse('{"title":"Contributing","description":"How to contribute new inventory modules and improvements to AzureScout.","frontmatter":{"description":"How to contribute new inventory modules and improvements to AzureScout."},"headers":[],"relativePath":"project/contributing.md","filePath":"project/contributing.md"}'),c={name:"project/contributing.md"};function n(i,e,s,d,l,u){return r(),o("div",null,[...e[0]||(e[0]=[a('<h1 id="contributing" tabindex="-1">Contributing <a class="header-anchor" href="#contributing" aria-label="Permalink to &quot;Contributing&quot;">​</a></h1><p>The full contributing guide is maintained in the repository root and rendered on GitHub.</p><p><a href="https://github.com/Hybrid-Solutions-Cloud/azure-scout/blob/main/CONTRIBUTING.md" class="md-button md-button--primary" target="_blank" rel="noreferrer">View CONTRIBUTING.md on GitHub</a></p><h2 id="quick-reference" tabindex="-1">Quick Reference <a class="header-anchor" href="#quick-reference" aria-label="Permalink to &quot;Quick Reference&quot;">​</a></h2><ul><li>Fork the repo and create a feature branch</li><li>New ARM collectors are declarative <code>.psd1</code> files under <code>manifests/collectors/&lt;Category&gt;/</code> — see <a href="./../reference/category-structure.html">Category Structure</a> for the 18 category folders and their <code>[ValidateSet]</code>/alias plumbing in <code>src/Invoke-AzureScout.ps1</code>. There is no <code>.ps1</code> template to copy from: a definition describes <em>what</em> to filter and <em>what</em> fields to produce (resource types, an optional filter, field expressions, the Excel export shape), and one shared interpreter runs it. See the decision record at <a href="./../design/decisions/declarative-collectors.html"><code>docs/design/decisions/declarative-collectors.md</code></a> for the full schema and worked examples.</li><li>New Entra ID collectors are catalog entries in <code>src/collect/Get-ScoutEntraQueryCatalog.ps1</code>, not separate files — see <a href="./../reference/entra-modules.html">Entra Modules</a> for the current 17-entry catalog.</li><li>Before you add a resource type, confirm Azure actually has it. Six collectors were retired 2026-07-31 because they declared types that do not exist (<code>Hybrid/ArcSites</code>, <code>Compute/CloudServices</code>, <code>Storage/DataLakeStoreGen1</code>, <code>Databases/POSTGRE</code>, <code>Monitor/AppInsightsContinuousExport</code>, <code>Monitor/AppInsightsWorkItems</code>) — see <a href="./../reference/category-reference.html#report-section-heading-category">Category Reference</a>. Every declared type is checked against a real Azure provider/type catalogue by <code>tests/ResourceTypeExistence.Tests.ps1</code>; see <a href="./testing.html#the-resource-type-existence-gate">Testing: the resource-type existence gate</a>.</li><li>Fixtures for the collector&#39;s own test are <strong>generated</strong> from its <code>.psd1</code> definition by <code>scripts/New-ScoutCollectorFixture.ps1</code>, not hand-written — see <a href="./testing.html">Testing</a> for how the golden tests use them.</li><li>Open a PR against <code>main</code> — describe what resource type you added and why.</li></ul><p>See <a href="./../reference/arm-modules.html">ARM Modules</a> and <a href="./../reference/entra-modules.html">Entra Modules</a> for the current catalog.</p>',6)])])}const f=t(c,[["render",n]]);export{p as __pageData,f as default};
